content.css:
@font-face {
  font-family: 'Plus Jakarta Sans';
  font-style: normal;
  font-weight: 200 800;
  font-display: swap;
  src: url(data:font/woff2;base64,) format('woff2-variations');
}
.visual-root {
  display: flex;
  flex-direction: column;
  width: 100%;
  height: 100%;
  box-sizing: border-box;
  overflow: hidden;
  font-weight: 400;
  font-variation-settings: "wght" 400;
  --ds-color-ink: #131B33;
  --ds-color-ink-soft: #4C5378;
  --ds-color-surface: #FFFFFF;
  --ds-color-surface-sunken: #F4F6FC;
  --ds-color-line: #DDE2F0;
  --ds-color-line-soft: #E9ECF6;
  --ds-radius-sm: 10px;
  --ds-radius-md: 18px;
  --ds-radius-lg: 28px;
  --ds-radius-pill: 999px;
  --ds-shadow-card: 0 1px 2px rgba(19, 27, 51, 0.04), 0 8px 24px -12px rgba(19, 27, 51, 0.18);
  background-color: var(--ds-color-surface);
  border: 1px solid var(--ds-color-line);
  border-radius: var(--ds-radius-lg);
  box-shadow: var(--ds-shadow-card);
  color: var(--ds-color-ink);
}
.chart-title {
  flex: 0 0 auto;
  padding: 14px 16px 0;
  font-family: inherit;
  font-size: 1.2rem;
  line-height: 1.3;
  font-weight: 800;
  font-variation-settings: "wght" 800;
  letter-spacing: -0.01em;
  color: var(--ds-color-ink);
}
.table-toolbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  padding: 12px 16px;
  flex: 0 0 auto;
  border-bottom: 1px solid var(--ds-color-line);
}
.table-search-input {
  flex: 1 1 auto;
  max-width: 220px;
  padding: 6px 12px;
  border: 1px solid var(--ds-color-line);
  border-radius: var(--ds-radius-sm);
  background-color: var(--ds-color-surface);
  color: var(--ds-color-ink);
  font-size: 12px;
  font-family: inherit;
  outline: none;
}
.table-search-input:focus {
  border-color: var(--primary-color);
}
.truncation-badge {
  flex: 0 0 auto;
  font-size: 11px;
  color: var(--ds-color-ink-soft);
  white-space: nowrap;
}
.custom-table-container {
  width: 100%;
  flex: 1 1 auto;
  min-height: 0;
  overflow: auto;
  box-sizing: border-box;
  position: relative;
  padding: 0 8px 0;
  scrollbar-width: thin;
  scrollbar-color: var(--ds-color-line) transparent;
}
.custom-table-container::-webkit-scrollbar {
  width: 10px;
  height: 10px;
}
.custom-table-container::-webkit-scrollbar-track {
  background: transparent;
}
.custom-table-container::-webkit-scrollbar-thumb {
  background-color: var(--ds-color-line);
  border-radius: 999px;
  border: 2px solid transparent;
  background-clip: padding-box;
}
.custom-table-container::-webkit-scrollbar-thumb:hover {
  background-color: var(--ds-color-ink-soft);
}
.empty-state {
  display: flex;
  align-items: center;
  justify-content: center;
  height: 100%;
  min-height: 80px;
  color: var(--ds-color-ink-soft);
  font-size: 13px;
  text-align: center;
  padding: 24px;
}
.table-skeleton {
  display: flex;
  flex-direction: column;
  gap: 10px;
  padding: 14px;
}
.skeleton-row {
  height: 16px;
  border-radius: 4px;
  background: linear-gradient(90deg, var(--ds-color-line-soft) 25%, var(--ds-color-surface-sunken) 50%, var(--ds-color-line-soft) 75%);
  background-size: 200% 100%;
  animation: skeleton-shimmer 1.4s ease-in-out infinite;
}
@keyframes skeleton-shimmer {
  0% {
    background-position: 200% 0;
  }
  100% {
    background-position: -200% 0;
  }
}
.custom-tooltip {
  position: fixed;
  z-index: 999999;
  pointer-events: none;
  font-size: 12px;
  min-width: 140px;
  max-width: 280px;
  border-radius: 18px;
  padding: 10px 14px;
  --ds-color-ink: #131B33;
  --ds-color-ink-soft: #4C5378;
  --ds-color-surface: #FFFFFF;
  --ds-color-line: #DDE2F0;
  --ds-color-line-soft: #E9ECF6;
  --ds-shadow-card: 0 1px 2px rgba(19, 27, 51, 0.04), 0 8px 24px -12px rgba(19, 27, 51, 0.18);
  box-shadow: var(--ds-shadow-card);
  background-color: var(--ds-color-surface);
  color: var(--ds-color-ink);
  border: 1px solid var(--ds-color-line);
  border-top: 3px solid var(--primary-color);
}
.custom-tooltip .tooltip-row {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  gap: 12px;
  padding: 3px 0;
}
.custom-tooltip .tooltip-row + .tooltip-row {
  border-top: 1px solid var(--ds-color-line-soft);
}
.custom-tooltip .tooltip-label {
  font-weight: 700;
  font-variation-settings: "wght" 700;
  text-transform: uppercase;
  font-size: 10px;
  letter-spacing: 0.06em;
  color: var(--ds-color-ink-soft);
  white-space: nowrap;
}
.custom-tooltip .tooltip-value {
  text-align: right;
  white-space: nowrap;
  font-weight: 600;
  font-variation-settings: "wght" 600;
}
.custom-table {
  width: 100%;
  border-collapse: separate;
  border-spacing: 0;
  font-size: 13px;
}
.custom-table th {
  text-align: left;
  padding: 12px 16px;
  cursor: pointer;
  user-select: none;
  background-color: var(--ds-color-surface);
  border-bottom: 1px solid var(--ds-color-line);
  font-weight: 700;
  font-variation-settings: "wght" 700;
  font-size: 11px;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--ds-color-ink-soft);
  position: sticky;
  top: 0;
}
.custom-table td {
  padding: 10px 16px;
  text-align: left;
  border-bottom: 1px solid var(--ds-color-line-soft);
}
.custom-table tr:focus-visible,
.custom-table th:focus-visible {
  outline: 2px solid var(--primary-color);
  outline-offset: -2px;
}
.custom-table tfoot td {
  position: sticky;
  bottom: 0;
  background-color: var(--ds-color-surface);
  color: var(--ds-color-ink);
  border-top: 2px solid var(--primary-color);
  border-bottom: none;
  font-weight: 700;
  font-variation-settings: "wght" 700;
  padding: 10px 16px;
}
.col-resize-handle {
  position: absolute;
  top: 0;
  right: -3px;
  width: 6px;
  height: 100%;
  cursor: col-resize;
  user-select: none;
  z-index: 5;
}
.frozen-col {
  position: sticky;
  z-index: 3;
  background-color: var(--ds-color-surface);
}
.custom-table.has-frozen-columns {
  table-layout: fixed !important;
}
.custom-table.has-frozen-columns th,
.custom-table.has-frozen-columns td {
  overflow-wrap: break-word;
}
.custom-table thead th.frozen-col {
  z-index: 4;
}
.high-contrast {
  box-shadow: none !important;
  background: none !important;
}
.high-contrast .custom-table th {
  background: none !important;
  box-shadow: none !important;
  border-bottom: 2px solid currentColor !important;
}
.high-contrast .custom-table tbody tr {
  background: none !important;
}
.sort-order-badge {
  font-size: 8px;
  background-color: var(--primary-color);
  color: #FFFFFF;
  border-radius: 50%;
  min-width: 12px;
  height: 12px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 0 2px;
}
.custom-table-row {
  cursor: pointer;
  transition: background-color 0.15s ease;
}
.custom-table-row:hover {
  background-color: var(--ds-color-surface-sunken);
}
.custom-table-row.is-faded {
  opacity: 0.35;
}
